bounded_host_request.command:
set -eu
cid=$(docker ps --filter label=com.docker.compose.service=videobot-poll --format '{{.ID}}')
if [ -z "$cid" ] || [ "$(printf '%s\n' "$cid" | wc -l)" -ne 1 ]; then printf 'SINGLE_POLLER_NOT_CONFIRMED\n'; exit 72; fi
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readPrivateToken} from './src/runtime/config.mjs';
const e=process.env;
const options=e.VIDEOBOT_DATABASE_URL_FILE?{connectionString:readPrivateToken(e.VIDEOBOT_DATABASE_URL_FILE)}:{host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readPrivateToken(e.VIDEOBOT_DB_PASSWORD_FILE)};
const pool=new pg.Pool({...options,max:1,connectionTimeoutMillis:5000});
let client;
try {
 client=await pool.connect();
 await client.query('BEGIN READ ONLY');
 await client.query("SET LOCAL statement_timeout='5s'");
 const queries={
  jobs:"SELECT status,count(*)::int AS n FROM videobot_owner_update_jobs GROUP BY status ORDER BY status",
  blocked:"SELECT count(*)::int AS n,count(DISTINCT q.owner_id)::int AS owners FROM videobot_owner_update_jobs q WHERE q.status='queued' AND EXISTS(SELECT 1 FROM videobot_owner_update_jobs p WHERE p.owner_id=q.owner_id AND p.update_id<q.update_id AND p.status='needs_reconcile')",
  receipts:"SELECT j.status AS job_status,coalesce(w.status,'missing') AS receipt_status,count(*)::int AS n FROM videobot_owner_update_jobs j LEFT JOIN videobot_webhook_updates w USING(update_id) WHERE j.status IN ('running','needs_reconcile') GROUP BY 1,2 ORDER BY 1,2",
  sessions:"SELECT coalesce(state->>'publishing','none') AS publishing,count(*)::int AS n FROM videobot_creator_sessions GROUP BY 1 ORDER BY 1"
 };
 for(const [k,sql] of Object.entries(queries)){const r=await client.query(sql); console.log(k+'='+JSON.stringify(r.rows));}
 await client.query('ROLLBACK');
} catch(err) {console.log('DIAGNOSTIC_FAILED='+(/^[0-9A-Z]{5}$/.test(err?.code??'')?err.code:'UNKNOWN'));process.exitCode=1;}
finally {client?.release();await pool.end();}
NODE
